// Public, unauthenticated route for external testers — deliberately not
// linked from the main nav (see footer.tsx / nav.tsx, neither reference
// this route) and deliberately NOT a page.tsx: a page.tsx here would be
// wrapped by the root layout's <Nav />/<Footer /> (see src/app/layout.tsx),
// which is exactly the site-chrome-around-the-content look this route
// must NOT have — per explicit instruction, this has to render pixel-
// for-pixel as the verified artifact preview
// (claude.ai/code/artifact/7bfd27ba-413d-420d-b38e-4f258870d6df), not
// restyled into the rest of the site. A Route Handler is the correct
// Next.js primitive for that: per Next's own docs, "They do not
// participate in layouts... like page," so returning a full raw HTML
// document here is the one way to guarantee nothing else in the app's
// layout tree touches this response.
//
// The HTML/CSS below is byte-for-byte the artifact's own source — title,
// style block (fonts already fully self-contained as base64 data URIs,
// nothing external to load), and body markup — reproduced as a template
// literal rather than hand-converted to JSX, specifically so there's no
// transcription drift from the exact, already-verified design.
//
// Content is the same Customer/Restaurant Owner/Admin guide verified
// live against premeal.onrender.com — every finding and caveat from
// that verification pass is preserved as-is, including the
// deliberately-omitted admin credential (see the Admin section).

const GUIDE_HTML = "<!DOCTYPE html>\n<html lang=\"en\">\n<head>\n<meta charset=\"utf-8\">\n<meta name=\"viewport\" content=\"width=device-width, initial-scale=1\">\n<title>Pre-Meal — Tester's Guide</title>\n<style>\n  @font-face {\n    font-family: 'Bricolage';\n    font-weight: 600;\n    font-style: normal;\n    font-display: swap;\n    src: url(data:font/woff2;base64,) format('woff2');\n  }\n  @font-face {\n    font-family: 'Bricolage';\n    font-weight: 800;\n    font-style: normal;\n    font-display: swap;\n    src: url(data:font/woff2;base64,) format('woff2');\n  }\n  @font-face {\n    font-family: 'Karla';\n    font-weight: 400;\n    font-style: normal;\n    font-display: swap;\n    src: url(data:font/woff2;base64,) format('woff2');\n  }\n  @font-face {\n    font-family: 'Karla';\n    font-weight: 700;\n    font-style: normal;\n    font-display: swap;\n    src: url(data:font/woff2;base64,) format('woff2');\n  }\n  @font-face {\n    font-family: 'Plex Mono';\n    font-weight: 400;\n    font-style: normal;\n    font-display: swap;\n    src: url(data:font/woff2;base64,) format('woff2');\n  }\n\n  :root {\n    --paper: #f3f4ef;\n    --paper-raised: #ffffff;\n    --ink: #201c15;\n    --muted: #6e6852;\n    --line: #dedacc;\n    --accent: #c15a2b;\n    --accent-ink: #ffffff;\n    --owner: #2b6e63;\n    --admin: #5b4b6e;\n    --good: #2f7d4f;\n    --good-bg: #e8f3ec;\n    --warn: #8a5a15;\n    --warn-bg: #faf0dc;\n    --danger: #b4423a;\n    --danger-bg: #fbebe8;\n    --code-bg: #eae7db;\n    --shadow: 0 1px 2px rgba(32, 28, 21, 0.06), 0 8px 24px -12px rgba(32, 28, 21, 0.18);\n  }\n\n  @media (prefers-color-scheme: dark) {\n    :root {\n      --paper: #171410;\n      --paper-raised: #201c15;\n      --ink: #f1ece1;\n      --muted: #a89d84;\n      --line: #362f22;\n      --accent: #e28654;\n      --accent-ink: #201200;\n      --owner: #63b0a1;\n      --admin: #a893c4;\n      --good: #6cc491;\n      --good-bg: #16261d;\n      --warn: #dba648;\n      --warn-bg: #2b2211;\n      --danger: #e58b81;\n      --danger-bg: #2c1815;\n      --code-bg: #2a251b;\n      --shadow: 0 1px 2px rgba(0, 0, 0, 0.3), 0 8px 24px -12px rgba(0, 0, 0, 0.5);\n    }\n  }\n  :root[data-theme=\"dark\"] {\n    --paper: #171410;\n    --paper-raised: #201c15;\n    --ink: #f1ece1;\n    --muted: #a89d84;\n    --line: #362f22;\n    --accent: #e28654;\n    --accent-ink: #201200;\n    --owner: #63b0a1;\n    --admin: #a893c4;\n    --good: #6cc491;\n    --good-bg: #16261d;\n    --warn: #dba648;\n    --warn-bg: #2b2211;\n    --danger: #e58b81;\n    --danger-bg: #2c1815;\n    --code-bg: #2a251b;\n    --shadow: 0 1px 2px rgba(0, 0, 0, 0.3), 0 8px 24px -12px rgba(0, 0, 0, 0.5);\n  }\n  :root[data-theme=\"light\"] {\n    --paper: #f3f4ef;\n    --paper-raised: #ffffff;\n    --ink: #201c15;\n    --muted: #6e6852;\n    --line: #dedacc;\n    --accent: #c15a2b;\n    --accent-ink: #ffffff;\n    --owner: #2b6e63;\n    --admin: #5b4b6e;\n    --good: #2f7d4f;\n    --good-bg: #e8f3ec;\n    --warn: #8a5a15;\n    --warn-bg: #faf0dc;\n    --danger: #b4423a;\n    --danger-bg: #fbebe8;\n    --code-bg: #eae7db;\n    --shadow: 0 1px 2px rgba(32, 28, 21, 0.06), 0 8px 24px -12px rgba(32, 28, 21, 0.18);\n  }\n\n  * { box-sizing: border-box; }\n  html { -webkit-text-size-adjust: 100%; }\n  body {\n    margin: 0;\n    background: var(--paper);\n    color: var(--ink);\n    font-family: 'Karla', ui-sans-serif, system-ui, sans-serif;\n    font-size: 16.5px;\n    line-height: 1.6;\n    -webkit-font-smoothing: antialiased;\n  }\n  a { color: var(--accent); text-decoration-thickness: 1.5px; text-underline-offset: 2px; }\n  a:focus-visible, button:focus-visible, .jump:focus-visible {\n    outline: 2.5px solid var(--accent);\n    outline-offset: 2px;\n    border-radius: 4px;\n  }\n\n  .masthead {\n    border-bottom: 1px solid var(--line);\n    padding: 2.6rem 1.5rem 2.2rem;\n  }\n  .masthead-inner { max-width: 760px; margin: 0 auto; }\n  .eyebrow {\n    font-family: 'Plex Mono', monospace;\n    font-size: 12px;\n    letter-spacing: 0.09em;\n    text-transform: uppercase;\n    color: var(--muted);\n    margin: 0 0 0.9rem;\n  }\n  h1.doctitle {\n    font-family: 'Bricolage', ui-sans-serif, sans-serif;\n    font-weight: 800;\n    font-size: clamp(2rem, 5vw, 2.75rem);\n    line-height: 1.06;\n    letter-spacing: -0.01em;\n    margin: 0 0 0.85rem;\n    text-wrap: balance;\n  }\n  .dek {\n    font-size: 1.05rem;\n    color: var(--muted);\n    max-width: 62ch;\n    margin: 0 0 1.5rem;\n  }\n  .testmode {\n    display: flex;\n    gap: 0.7rem;\n    align-items: flex-start;\n    background: var(--good-bg);\n    border: 1px solid color-mix(in srgb, var(--good) 35%, transparent);\n    border-radius: 10px;\n    padding: 0.9rem 1.1rem;\n    font-size: 0.92rem;\n    color: var(--ink);\n  }\n  .testmode b { color: var(--good); }\n\n  .jumpbar {\n    position: sticky;\n    top: 0;\n    z-index: 20;\n    background: color-mix(in srgb, var(--paper) 92%, transparent);\n    backdrop-filter: blur(8px);\n    border-bottom: 1px solid var(--line);\n    padding: 0.7rem 1.5rem;\n  }\n  .jumpbar-inner {\n    max-width: 760px;\n    margin: 0 auto;\n    display: flex;\n    gap: 0.5rem;\n    overflow-x: auto;\n  }\n  .jump {\n    font-family: 'Plex Mono', monospace;\n    font-size: 12.5px;\n    letter-spacing: 0.03em;\n    white-space: nowrap;\n    padding: 0.4rem 0.8rem;\n    border-radius: 999px;\n    border: 1px solid var(--line);\n    color: var(--ink);\n    text-decoration: none;\n    background: var(--paper-raised);\n    flex-shrink: 0;\n  }\n  .jump.c { border-color: color-mix(in srgb, var(--accent) 45%, var(--line)); }\n  .jump.o { border-color: color-mix(in srgb, var(--owner) 45%, var(--line)); }\n  .jump.a { border-color: color-mix(in srgb, var(--admin) 45%, var(--line)); }\n\n  main { max-width: 760px; margin: 0 auto; padding: 0 1.5rem 5rem; }\n\n  section.role { padding-top: 3.2rem; scroll-margin-top: 4rem; }\n  .role-tag {\n    display: inline-flex;\n    align-items: center;\n    gap: 0.5rem;\n    font-family: 'Plex Mono', monospace;\n    font-size: 12px;\n    letter-spacing: 0.08em;\n    text-transform: uppercase;\n    padding: 0.3rem 0.7rem 0.3rem 0.6rem;\n    border-radius: 999px;\n    margin-bottom: 1rem;\n  }\n  .role-tag .dot { width: 7px; height: 7px; border-radius: 50%; }\n  .role.customer .role-tag { background: color-mix(in srgb, var(--accent) 14%, transparent); color: var(--accent); }\n  .role.customer .role-tag .dot { background: var(--accent); }\n  .role.owner .role-tag { background: color-mix(in srgb, var(--owner) 16%, transparent); color: var(--owner); }\n  .role.owner .role-tag .dot { background: var(--owner); }\n  .role.admin .role-tag { background: color-mix(in srgb, var(--admin) 16%, transparent); color: var(--admin); }\n  .role.admin .role-tag .dot { background: var(--admin); }\n\n  h2.role-title {\n    font-family: 'Bricolage', sans-serif;\n    font-weight: 800;\n    font-size: 2rem;\n    letter-spacing: -0.01em;\n    margin: 0 0 0.6rem;\n    text-wrap: balance;\n  }\n  .role-dek { color: var(--muted); font-size: 1rem; max-width: 60ch; margin: 0 0 2.2rem; }\n\n  h3.sub {\n    font-family: 'Bricolage', sans-serif;\n    font-weight: 700;\n    font-size: 1.2rem;\n    margin: 2.6rem 0 0.3rem;\n    padding-top: 1.6rem;\n    border-top: 1px solid var(--line);\n  }\n  section.role > h3.sub:first-of-type { border-top: none; padding-top: 0; margin-top: 0; }\n  .sub-note { color: var(--muted); font-size: 0.92rem; margin: 0 0 1.1rem; }\n\n  ol.steps {\n    list-style: none;\n    counter-reset: step;\n    margin: 0 0 1.3rem;\n    padding: 0;\n  }\n  ol.steps > li {\n    counter-increment: step;\n    position: relative;\n    padding: 0.45rem 0 0.45rem 2.4rem;\n    font-size: 0.98rem;\n  }\n  ol.steps > li::before {\n    content: counter(step);\n    position: absolute;\n    left: 0;\n    top: 0.45rem;\n    width: 1.65rem;\n    height: 1.65rem;\n    border-radius: 50%;\n    background: var(--code-bg);\n    color: var(--muted);\n    font-family: 'Plex Mono', monospace;\n    font-size: 0.8rem;\n    display: flex;\n    align-items: center;\n    justify-content: center;\n  }\n  .role.customer ol.steps > li::before { color: var(--accent); }\n  .role.owner ol.steps > li::before { color: var(--owner); }\n  .role.admin ol.steps > li::before { color: var(--admin); }\n\n  ul.feature-list { list-style: none; margin: 0 0 1.3rem; padding: 0; }\n  ul.feature-list > li {\n    padding: 0.55rem 0;\n    border-bottom: 1px dashed var(--line);\n    font-size: 0.98rem;\n  }\n  ul.feature-list > li:last-child { border-bottom: none; }\n  ul.feature-list > li > b { font-family: 'Bricolage'; font-weight: 700; font-size: 0.98rem; }\n\n  code, .ui {\n    font-family: 'Plex Mono', monospace;\n    font-size: 0.85em;\n    background: var(--code-bg);\n    padding: 0.1em 0.4em;\n    border-radius: 4px;\n    white-space: nowrap;\n  }\n\n  .callout {\n    border-radius: 10px;\n    padding: 0.95rem 1.1rem;\n    font-size: 0.92rem;\n    margin: 1.1rem 0 1.6rem;\n    border: 1px solid var(--line);\n  }\n  .callout p { margin: 0.3em 0; }\n  .callout p:first-child { margin-top: 0; }\n  .callout p:last-child { margin-bottom: 0; }\n  .callout.warn { background: var(--warn-bg); border-color: color-mix(in srgb, var(--warn) 40%, transparent); }\n  .callout.warn .callout-label { color: var(--warn); }\n  .callout.danger { background: var(--danger-bg); border-color: color-mix(in srgb, var(--danger) 40%, transparent); }\n  .callout.danger .callout-label { color: var(--danger); }\n  .callout.blocked { background: var(--code-bg); border-style: dashed; }\n  .callout.blocked .callout-label { color: var(--muted); }\n  .callout-label {\n    display: block;\n    font-family: 'Plex Mono', monospace;\n    font-size: 11px;\n    letter-spacing: 0.07em;\n    text-transform: uppercase;\n    margin-bottom: 0.4rem;\n    font-weight: 600;\n  }\n\n  footer.report {\n    margin-top: 4rem;\n    padding-top: 2.2rem;\n    border-top: 2px solid var(--ink);\n  }\n  footer.report h2 {\n    font-family: 'Bricolage'; font-weight: 800; font-size: 1.5rem; margin: 0 0 0.7rem;\n  }\n  footer.report p { color: var(--muted); max-width: 62ch; }\n  footer.report .example {\n    background: var(--paper-raised);\n    border: 1px solid var(--line);\n    border-radius: 10px;\n    padding: 1rem 1.2rem;\n    margin-top: 1rem;\n    box-shadow: var(--shadow);\n    font-size: 0.92rem;\n  }\n  footer.report .example dt { font-family: 'Plex Mono', monospace; font-size: 11px; text-transform: uppercase; letter-spacing: 0.06em; color: var(--muted); margin-top: 0.7rem; }\n  footer.report .example dt:first-child { margin-top: 0; }\n  footer.report .example dd { margin: 0.15rem 0 0; }\n  .foot-note { color: var(--muted); font-size: 0.85rem; margin-top: 2.5rem; }\n\n  @media (max-width: 480px) {\n    body { font-size: 16px; }\n    .masthead { padding: 2rem 1.1rem 1.6rem; }\n    main { padding: 0 1.1rem 4rem; }\n    .jumpbar { padding: 0.6rem 1.1rem; }\n  }\n</style>\n</head>\n<body>\n<div class=\"masthead\">\n  <div class=\"masthead-inner\">\n    <p class=\"eyebrow\">Pre-Meal · Tester's Guide</p>\n    <h1 class=\"doctitle\">Everything to click, in the order to click it.</h1>\n    <p class=\"dek\">Three roles, one app: Customer, Restaurant Owner, and Admin. Every step below was walked through live on <a href=\"https://premeal.onrender.com\">premeal.onrender.com</a> to confirm it's accurate — not written from memory.</p>\n    <div class=\"testmode\">\n      <span>💳</span>\n      <span><b>Payments are in Stripe test mode.</b> No real charges anywhere in this guide. When a step asks for card details, use <code>4242 4242 4242 4242</code>, any future expiry date, any 3-digit CVC, and any postal code.</span>\n    </div>\n  </div>\n</div>\n\n<div class=\"jumpbar\">\n  <div class=\"jumpbar-inner\">\n    <a class=\"jump c\" href=\"#customer\">Customer</a>\n    <a class=\"jump o\" href=\"#owner\">Restaurant Owner</a>\n    <a class=\"jump a\" href=\"#admin\">Admin</a>\n    <a class=\"jump\" href=\"#reporting\">Reporting</a>\n  </div>\n</div>\n\n<main>\n\n  <!-- ============ CUSTOMER ============ -->\n  <section class=\"role customer\" id=\"customer\">\n    <span class=\"role-tag\"><span class=\"dot\"></span>Role 1 of 3</span>\n    <h2 class=\"role-title\">Customer</h2>\n    <p class=\"role-dek\">Browse, order, track, and review — the everyday shopper side of the app.</p>\n\n    <h3 class=\"sub\">Account setup</h3>\n    <ol class=\"steps\">\n      <li>Go to <code>premeal.onrender.com</code>.</li>\n      <li>Click <span class=\"ui\">Sign up</span>, top right.</li>\n      <li>Leave the role toggle on <span class=\"ui\">I'm a customer</span> (the other option, <span class=\"ui\">I run a restaurant</span>, is for the Restaurant Owner section below).</li>\n      <li>Fill in <span class=\"ui\">Name</span>, <span class=\"ui\">Email</span>, and <span class=\"ui\">Password</span> (minimum 8 characters).</li>\n      <li>Click <span class=\"ui\">Sign up</span>.</li>\n      <li>You land back on the homepage, now logged in — the top-right nav changes to <span class=\"ui\">My orders</span>, <span class=\"ui\">Addresses</span>, your name, and <span class=\"ui\">Log out</span>.</li>\n      <li>An amber banner should appear near the top of every page: \"Please verify your email (your@email) to secure your account.\" — a real verification email should follow shortly.</li>\n    </ol>\n\n    <h3 class=\"sub\">Core workflow — browse, order, track</h3>\n    <ol class=\"steps\">\n      <li>On the homepage, type a full address into the <span class=\"ui\">Full address</span> box and click <span class=\"ui\">Search</span>.</li>\n      <li>Under \"Find your favourite,\" optionally narrow by cuisine chip or tick <span class=\"ui\">4+ rated</span>, and change <span class=\"ui\">SORT BY</span> (Best match / Nearest / Min order / Highest rated).</li>\n      <li>Click a restaurant card.</li>\n      <li>Under \"Choose a delivery slot,\" click an available date/time tile.</li>\n      <li>Find a menu item and click its <span class=\"ui\">+</span> button. If the item has required choices (e.g. a spice level), a panel opens — pick the required option(s), tick any optional extras, then click <span class=\"ui\">Add £X.XX</span>.</li>\n      <li>Repeat for anything else you want — items stack up in the \"Your order\" panel on the right.</li>\n      <li>Under \"DELIVERY DETAILS,\" pick a saved address or select <span class=\"ui\">Use a different address</span> and type one in.</li>\n      <li>Optional: enter a promo code and click <span class=\"ui\">Apply</span>.</li>\n      <li>Enter the test card details (see the note at the top of this guide) in the payment box.</li>\n      <li>Click <span class=\"ui\">Pay & place order — £X.XX</span>.</li>\n      <li>You land on an order-tracking page: \"Waiting for restaurant to confirm\" with a 30-minute countdown. Nothing is charged yet.</li>\n      <li>The restaurant now has to accept it (see the Restaurant Owner section) before this goes further — that part can't be tested from the customer side alone.</li>\n      <li>Once a restaurant owner has accepted, dispatched, and marked it delivered, refresh this same order page: it now shows a delivered state with a star-rating box underneath.</li>\n    </ol>\n    <div class=\"callout blocked\">\n      <span class=\"callout-label\">Needs a second tester</span>\n      <p>Steps 12–13 depend on someone testing the Restaurant Owner role at the same time to actually accept and deliver the order. Coordinate, or expect your order to just sit \"awaiting confirmation.\"</p>\n    </div>\n\n    <h3 class=\"sub\">Secondary features</h3>\n    <ul class=\"feature-list\">\n      <li><b>Order history</b> — click <span class=\"ui\">My orders</span> in the nav. Filter pills across the top: All / Awaiting confirmation / Confirmed / Out for delivery / Delivered / Declined/expired. Results are paginated.</li>\n      <li><b>Leaving a review</b> — open any Delivered order from your history, click a star rating (1–5) under \"How was it?\", optionally add a comment, click <span class=\"ui\">Submit review</span>. Confirmed working live — this used to need checking, it's real and functional. Once submitted, it's locked in as \"Your review\" (no edit).</li>\n      <li><b>Reporting a problem</b> — on a Delivered order's page, <span class=\"ui\">Report a problem with this order</span> opens a dispute, which holds back the restaurant's payout until an admin resolves it. Real and functional — use it sparingly during testing, since it triggers an actual moderation queue.</li>\n      <li><b>Saved addresses</b> — click <span class=\"ui\">Addresses</span> in the nav. <span class=\"ui\">+ Add an address</span> to save one (optional label like Home/Work, full address via autocomplete). <span class=\"ui\">Make default</span> / <span class=\"ui\">Remove</span> on any saved one.</li>\n      <li><b>Forgot password</b> — <span class=\"ui\">Forgot password?</span> link on the login page sends a reset email.</li>\n    </ul>\n    <div class=\"callout blocked\">\n      <span class=\"callout-label\">Doesn't exist yet — please don't hunt for it</span>\n      <p>There is no account-settings page on the web — nowhere to change your name or password, or delete your account. Account deletion exists as a backend endpoint built for the mobile app's Account screen specifically; there's no web equivalent. If this needs testing, it has to wait for the mobile app.</p>\n    </div>\n  </section>\n\n  <!-- ============ OWNER ============ -->\n  <section class=\"role owner\" id=\"owner\">\n    <span class=\"role-tag\"><span class=\"dot\"></span>Role 2 of 3</span>\n    <h2 class=\"role-title\">Restaurant Owner</h2>\n    <p class=\"role-dek\">Everything a restaurant needs to get listed, take orders, and get paid.</p>\n\n    <h3 class=\"sub\">Account setup</h3>\n    <ol class=\"steps\">\n      <li>Go to <code>premeal.onrender.com/signup</code>.</li>\n      <li>Click <span class=\"ui\">I run a restaurant</span>.</li>\n      <li>Fill in your name, email, password, plus <span class=\"ui\">Restaurant name</span> and <span class=\"ui\">Cuisine</span>.</li>\n      <li>Click <span class=\"ui\">Sign up</span> — you land on <code>/restaurant/dashboard</code>.</li>\n      <li>A \"Get ready to go live\" card shows a progress bar and checklist: Add menu items, Set up delivery days, Set your location, Connect payouts, Get approved by Pre-Meal, Pay the one-time signup fee.</li>\n    </ol>\n    <div class=\"callout warn\">\n      <span class=\"callout-label\">Not visible to customers until…</span>\n      <p>A new restaurant stays hidden from customer search until <em>both</em> every checklist item above is done <em>and</em> an admin approves it (see the Admin section). Expect \"Not live\" / \"Not visible to customers yet\" on your own dashboard until then.</p>\n    </div>\n\n    <h3 class=\"sub\">Core workflow — running the day</h3>\n    <ol class=\"steps\">\n      <li><b>Confirm orders:</b> on the Dashboard, \"Needs a response\" lists anything awaiting you, with a countdown. <span class=\"ui\">Decline</span> or <span class=\"ui\">Accept</span> each one — unanswered orders auto-decline and refund after 30 minutes.</li>\n      <li><b>Pause new orders:</b> the <span class=\"ui\">Accepting new orders</span> toggle sits right under your restaurant name on the Dashboard — flip it off any time you need to stop new orders temporarily (fully booked, closing early, etc.), flip it back on when ready.</li>\n      <li><b>Dispatch:</b> once accepted, an order moves to \"Confirmed — ready to dispatch\" — click <span class=\"ui\">Mark out for delivery</span> when it's on its way (or <span class=\"ui\">Cancel</span> to refund the customer instead).</li>\n      <li><b>Complete delivery:</b> under \"Out for delivery,\" click <span class=\"ui\">Mark delivered</span> once it's arrived.</li>\n      <li><b>Manage the menu:</b> sidebar → Menu. Add/rename/remove/reorder categories under \"Menu categories.\" Click <span class=\"ui\">+ New item</span> for a new dish — Name, Description, Price, and either <span class=\"ui\">Upload photo</span> (jpg/png/webp/gif, 5MB max) or paste a photo URL directly. <span class=\"ui\">Edit</span> to change any item later (including replacing its photo), <span class=\"ui\">Add-ons</span> to attach modifier groups (e.g. required spice level, optional extras with their own prices), <span class=\"ui\">Hide</span>/<span class=\"ui\">Show</span> to toggle customer visibility without deleting, <span class=\"ui\">Remove</span> to delete outright.</li>\n      <li><b>Settings:</b> sidebar → Settings — restaurant photo, name, address, delivery radius (miles), delivery fee (£), minimum order (£), plus the customer-facing about/description, contact phone, and contact email. <span class=\"ui\">Save settings</span>.</li>\n    </ol>\n\n    <h3 class=\"sub\">Secondary features</h3>\n    <ul class=\"feature-list\">\n      <li><b>Drivers</b> — sidebar → Drivers. Invite someone by email; they show \"Awaiting response\" until they accept from their own driver dashboard, then \"Active.\" <span class=\"ui\">Remove</span> to revoke.</li>\n      <li><b>Delivery schedule</b> — sidebar → Deliveries. Set a delivery window (start/end time), capacity per day, a cutoff hour, tick which days of the week you deliver, choose how many days ahead to generate, then <span class=\"ui\">Generate schedule</span> — this creates the real bookable slots customers pick from. \"Upcoming days\" shows booked-vs-capacity for each.</li>\n      <li><b>Payouts</b> — sidebar → Payouts. Shows Stripe Connect onboarding status; once set up, payouts fire automatically after each delivered order's dispute window closes.</li>\n      <li><b>Reviews</b> — sidebar → Reviews. Read-only list of what customers have said, with your running average.</li>\n      <li><b>Full order history</b> — sidebar → Orders. Everything beyond the live Dashboard view, filterable by status and delivery date, with a \"Prep summary\" (aggregated item counts across whatever's currently filtered — genuinely useful for kitchen prep) and <span class=\"ui\">Export CSV</span>.</li>\n    </ul>\n  </section>\n\n  <!-- ============ ADMIN ============ -->\n  <section class=\"role admin\" id=\"admin\">\n    <span class=\"role-tag\"><span class=\"dot\"></span>Role 3 of 3</span>\n    <h2 class=\"role-title\">Admin</h2>\n    <p class=\"role-dek\">Platform oversight: approvals, disputes, promotions, and broadcasts.</p>\n\n    <div class=\"callout danger\">\n      <span class=\"callout-label\">Read this before anything else</span>\n      <p><b>There is no self-serve way to become an admin, anywhere in the app — deliberately.</b> Signing up only ever offers Customer or Restaurant Owner; that restriction is enforced at the form level, not just hidden. Promoting a real account to Admin is a manual database change only the developer can make.</p>\n      <p>Practically: testers cannot get admin access on their own. If the steps below need testing, that has to happen either directly by the developer, or by the developer promoting one specific trusted tester's account and sharing that login privately — never inside a guide handed to external testers, since an admin account can approve or reject any restaurant, resolve any dispute, and email every single user on the platform.</p>\n    </div>\n\n    <h3 class=\"sub\">Core workflow (whoever holds admin access)</h3>\n    <ol class=\"steps\">\n      <li><b>Overview</b> (<code>/admin</code>) — platform stats at a glance: orders today/this week/this month, commission revenue, signup fee revenue, top restaurants by order volume. Banners for pending restaurant approvals or open disputes appear at the top automatically whenever there are any.</li>\n      <li><b>Approve or reject a restaurant</b> — sidebar → Restaurants, filter Pending/Approved/Rejected/All. Each card shows the owner's name/email, menu item count, delivery slots set up, and signup-fee-paid status. Click <span class=\"ui\">Approve</span>, or <span class=\"ui\">Reject</span> with a reason (shown to the owner).</li>\n      <li><b>Resolve a dispute</b> — sidebar → Disputes, Open / All (incl. resolved). Each shows the customer's complaint against the order detail. <span class=\"ui\">Side with restaurant — release payout</span> or <span class=\"ui\">Side with customer — refund</span>, with an optional internal note.</li>\n    </ol>\n\n    <h3 class=\"sub\">Secondary features</h3>\n    <ul class=\"feature-list\">\n      <li><b>Promotions</b> — sidebar → Promotions. <span class=\"ui\">+ New promo code</span>: percentage or fixed-£ off, optional minimum order, optional maximum total redemptions. <span class=\"ui\">Activate</span>/<span class=\"ui\">Deactivate</span> any existing code.</li>\n      <li><b>Broadcast</b> — sidebar → Broadcast. One-off email to every Customer, every Restaurant owner, or Everyone. Sends immediately on confirmation and can't be undone — there's a confirm dialog for exactly this reason.</li>\n      <li><b>Feature flags</b> — sidebar → Feature flags. Create a flag by key (e.g. <code>subscriptions</code>), then Enable/Disable it. A feature with no flag row here defaults to enabled.</li>\n    </ul>\n    <div class=\"callout warn\">\n      <span class=\"callout-label\">Careful with these two</span>\n      <p><span class=\"ui\">Broadcast</span> emails real inboxes the instant you confirm it, and approving/rejecting a restaurant affects a real applicant. Neither was actually triggered while writing this guide, for exactly that reason — both were confirmed accurate by reading the page and its code, not by firing them for real.</p>\n    </div>\n  </section>\n\n  <footer class=\"report\" id=\"reporting\">\n    <h2>Reporting back</h2>\n    <p>For every step: just what you expected to happen, and what actually happened. That's the whole format — you don't need to guess why something broke, just where it broke.</p>\n    <div class=\"example\">\n      <dl>\n        <dt>Step</dt>\n        <dd>Restaurant Owner → Core workflow → step 5, clicking \"Upload photo\"</dd>\n        <dt>Expected</dt>\n        <dd>A file picker opens, then the photo shows in the item row after upload.</dd>\n        <dt>Actual</dt>\n        <dd>File picker opened fine, but the photo never appeared — item still shows the placeholder icon.</dd>\n      </dl>\n    </div>\n    <p class=\"foot-note\">Verified live against premeal.onrender.com. If anything above stops matching what you see, that's worth reporting too.</p>\n  </footer>\n</main>\n</body>\n</html>\n";

export async function GET() {
  return new Response(GUIDE_HTML, {
    headers: { "Content-Type": "text/html; charset=utf-8" },
  });
}
